Run python - <<'PY'
from pathlib import Path
for path in [Path('README.md'), Path('docs/getting-started.md')]:
    text = path.read_text()
    for frag in ['[INSTALL.md](INSTALL.md)', '[docs/getting-started.md](docs/getting-started.md)', '[AGENTS.md](AGENTS.md)', '[INSTALL.md](../INSTALL.md)', '[AGENTS.md](../AGENTS.md)']:
        if frag in text:
            target = frag.split('](')[1][:-1]
            resolved = (path.parent / target).resolve()
            print(path, target, resolved.exists())
PY

